#!/usr/bin/env python3
"""Compile structured page content and design tokens to static Jekyll includes.

The source of truth is JSON, not hand-written page markup or style variables.
Generated includes remain ordinary static HTML/CSS for accessibility, SEO,
GitHub Pages, and visitors who have JavaScript disabled.

Usage:
    python .github/scripts/generate_site_content.py
    python .github/scripts/generate_site_content.py --check
"""

import argparse
import html
import json
import re
import sys
from pathlib import Path

from home_render import render_hero, render_sections
from utility_pages import render_contact, render_not_found

ROOT = Path(__file__).resolve().parents[2]
DETAILS = ROOT / "_data" / "developer_details.json"
ABOUT = ROOT / "_data" / "about_content.json"
HOME = ROOT / "_data" / "home_content.json"
TOKENS = ROOT / "_data" / "design_tokens.json"
CONTACT = ROOT / "_data" / "contact_page.json"
NOT_FOUND = ROOT / "_data" / "not_found_page.json"
OUTPUTS = {
    "core": ROOT / "_includes" / "generated" / "developer-core.html",
    "philosophy": ROOT / "_includes" / "generated" / "developer-philosophy.html",
    "tokens": ROOT / "_includes" / "generated" / "design-tokens.css",
    "about_intro": ROOT / "_includes" / "generated" / "about-intro.html",
    "about_sections": ROOT / "_includes" / "generated" / "about-sections.html",
    "home_hero": ROOT / "_includes" / "generated" / "home-hero.html",
    "home_sections": ROOT / "_includes" / "generated" / "home-sections.html",
    "contact": ROOT / "_includes" / "generated" / "contact-page.html",
    "not_found": ROOT / "_includes" / "generated" / "not-found-page.html",
    "stylesheet": ROOT / "assets" / "css" / "main.css",
    "terminal": ROOT / "terminal.json",
    "search": ROOT / "search.json",
}
TOKEN_NAME = re.compile(r"[a-z][a-z0-9-]*\Z")
UNSAFE_CSS = re.compile(r"[;{}<>@\x00-\x1f]|/\*|\*/|url\s*\(", re.I)
GENERATED_HTML = "<!-- Generated by .github/scripts/generate_site_content.py; edit _data/developer_details.json. -->"
GENERATED_CSS = "/* Generated by .github/scripts/generate_site_content.py; edit _data/design_tokens.json. */"
GENERATED_ABOUT = "<!-- Generated by .github/scripts/generate_site_content.py; edit _data/about_content.json. -->"


def load_object(path):
    data = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(data, dict):
        raise ValueError(f"{path}: expected a JSON object")
    return data


def string(value, context):
    if not isinstance(value, str) or not value.strip() or len(value) > 2000:
        raise ValueError(f"{context}: expected non-empty text up to 2000 characters")
    if any(ord(char) < 32 and char not in "\n\t" for char in value):
        raise ValueError(f"{context}: contains control characters")
    # Liquid runs after include expansion; escape opening braces in prose
    # to prevent data values from injecting template expressions.
    return html.escape(value.strip(), quote=True).replace("{", "&#123;")


def strings(data, key):
    values = data.get(key)
    if not isinstance(values, list) or not values:
        raise ValueError(f"{key}: expected a non-empty list")
    return [string(item, f"{key}[{index}]") for index, item in enumerate(values)]


def pairs(data, key, first, second):
    values = data.get(key)
    if not isinstance(values, list) or not values:
        raise ValueError(f"{key}: expected a non-empty list")
    names = set()
    output = []
    for index, item in enumerate(values):
        if not isinstance(item, dict) or set(item) != {first, second}:
            raise ValueError(f"{key}[{index}]: expected {first!r} and {second!r}")
        name = string(item[first], f"{key}[{index}].{first}")
        detail = string(item[second], f"{key}[{index}].{second}")
        if name in names:
            raise ValueError(f"{key}: duplicate {first}: {name}")
        names.add(name)
        output.append((name, detail))
    return output


def render_core(data):
    interests = strings(data, "engineering_interests")
    platforms = pairs(data, "platforms", "name", "description")
    tools = pairs(data, "tools", "name", "description")
    lines = [
        GENERATED_HTML,
        '<section class="page-section">',
        '  <h2 id="engineering-interests">Engineering interests</h2>',
        '  <ul class="bullet-list">',
    ]
    lines.extend(f"    <li>{interest}</li>" for interest in interests)
    lines.extend(['  </ul>', '</section>'])
    for heading, anchor, values in (("Platforms", "platforms", platforms),
                                     ("Tools", "tools", tools)):
        lines.extend([
            '<section class="page-section">',
            f'  <h2 id="{anchor}">{heading}</h2>',
            '  <dl class="spec-list">',
        ])
        for name, description in values:
            lines.extend([
                '    <div class="spec-list__row">',
                f'      <dt class="spec-list__term">{name}</dt>',
                f'      <dd>{description}</dd>',
                '    </div>',
            ])
        lines.extend(['  </dl>', '</section>'])
    return "\n".join(lines) + "\n"


def render_philosophy(data):
    learning = string(data.get("learning_and_exploration"), "learning_and_exploration")
    principles = pairs(data, "principles", "title", "description")
    lines = [
        GENERATED_HTML,
        '<section class="page-section">',
        '  <h2 id="learning-and-exploration">Learning and exploration</h2>',
        f'  <p>{learning}</p>',
        '</section>',
        '<section class="page-section">',
        '  <h2 id="development-philosophy">Development philosophy</h2>',
        '  <ol class="principles">',
    ]
    for title, description in principles:
        lines.extend([
            '    <li>',
            '      <div>',
            f'        <h3>{title}</h3>',
            f'        <p>{description}</p>',
            '      </div>',
            '    </li>',
        ])
    lines.extend(['  </ol>', '</section>'])
    return "\n".join(lines) + "\n"


def render_tokens(data):
    if not data:
        raise ValueError("design tokens: no groups")
    lines = [GENERATED_CSS]
    all_names = set()
    for group, variables in data.items():
        if not isinstance(group, str) or not re.fullmatch(r"[A-Za-z ]{2,40}", group):
            raise ValueError(f"Invalid token group: {group!r}")
        if not isinstance(variables, dict) or not variables:
            raise ValueError(f"{group}: expected a non-empty object")
        lines.append(f"  /* {group} */")
        for name, value in variables.items():
            if not isinstance(name, str) or not TOKEN_NAME.fullmatch(name):
                raise ValueError(f"Invalid CSS token: {name!r}")
            if name in all_names:
                raise ValueError(f"Duplicate CSS token: {name}")
            if not isinstance(value, str) or not value.strip() or UNSAFE_CSS.search(value):
                raise ValueError(f"Unsafe CSS value for {name}")
            all_names.add(name)
            lines.append(f"  --{name}: {value.strip()};")
        lines.append("")
    return "\n".join(lines).rstrip() + "\n"


# The names of dynamic Jekyll widgets and links are explicitly allowlisted:
# JSON can supply prose, but cannot inject Liquid statements or arbitrary HTML.
ABOUT_WIDGETS = {
    "focus": [
        '  <ul class="bullet-list">',
        '    {%- for area in site.data.focus %}',
        '    <li><strong>{{ area.title }}</strong> — {{ area.summary }}</li>',
        '    {%- endfor %}',
        '  </ul>',
    ],
    "products": [
        '  {% include profile-list.html group="products" variant="card" class="link-grid" %}',
    ],
    "community": [
        '  {% include profile-list.html items=site.data.social.community variant="card" class="link-grid" %}',
    ],
}
ABOUT_ACTIONS = {
    "developer": [
        '  <p>{% include link.html url="/developer/" label="See the full developer profile" class="text-link" arrow=true %}</p>',
    ],
    "github": [
        '  <div class="button-row">',
        '    {% include link.html url=site.data.social.profiles.github.url label="GitHub profile" icon="github" class="button button--secondary" %}',
        '  </div>',
    ],
    "technologies": [
        '  <p>{% include link.html url="/developer/#technologies" label="All technologies" class="text-link" arrow=true %}</p>',
    ],
    "philosophy": [
        '  <p>{% include link.html url="/developer/#development-philosophy" label="Development philosophy" class="text-link" arrow=true %}</p>',
    ],
}


def render_about_intro(data):
    """The prose beside the identity card; the card keeps live Liquid data."""
    paragraphs = strings(data, "intro")
    lines = [GENERATED_ABOUT]
    lines.extend(f"    <p>{paragraph}</p>" for paragraph in paragraphs)
    return "\n".join(lines) + "\n"


def render_about_sections(data):
    """Render checked, escaped prose while retaining allowlisted site widgets."""
    sections = data.get("sections")
    if not isinstance(sections, list) or not sections:
        raise ValueError("about.sections: expected a non-empty list")
    cta = data.get("cta")
    if not isinstance(cta, dict) or set(cta) != {"heading", "paragraph"}:
        raise ValueError("about.cta: expected heading and paragraph")
    lines = [GENERATED_ABOUT]
    headings = set()
    for index, section in enumerate(sections):
        if not isinstance(section, dict) or not {"heading", "paragraphs"} <= set(section):
            raise ValueError(f"about.sections[{index}]: expected heading and paragraphs")
        if set(section) - {"heading", "paragraphs", "widget", "action"}:
            raise ValueError(f"about.sections[{index}]: unknown fields")
        heading = string(section["heading"], f"about.sections[{index}].heading")
        if heading.casefold() in headings:
            raise ValueError(f"about.sections: duplicate heading {heading}")
        headings.add(heading.casefold())
        paragraphs = strings(section, "paragraphs")
        widget = section.get("widget")
        action = section.get("action")
        if widget is not None and (not isinstance(widget, str) or widget not in ABOUT_WIDGETS):
            raise ValueError(f"about.sections[{index}]: unknown widget")
        if action is not None and (not isinstance(action, str) or action not in ABOUT_ACTIONS):
            raise ValueError(f"about.sections[{index}]: unknown action")
        lines.extend([
            '<section class="page-section">',
            f'  <h2>{heading}</h2>',
        ])
        lines.extend(f"  <p>{paragraph}</p>" for paragraph in paragraphs)
        if widget is not None:
            lines.extend(ABOUT_WIDGETS[widget])
        if action is not None:
            lines.extend(ABOUT_ACTIONS[action])
        lines.append("</section>")
        lines.append("")
    lines.extend([
        '<div class="cta-panel">',
        f'  <h2 class="cta-panel__title">{string(cta["heading"], "about.cta.heading")}</h2>',
        f'  <p>{string(cta["paragraph"], "about.cta.paragraph")}</p>',
        '  <div class="button-row">',
        '    {% include link.html url="/contact/" label="Contact me" class="button button--primary" arrow=true %}',
        '    {% include link.html url=site.data.social.profiles.github.url label="GitHub" icon="github" class="button button--secondary" %}',
        '  </div>',
        '</div>',
    ])
    return "\n".join(lines) + "\n"


def generated_files():
    details = load_object(DETAILS)
    tokens = load_object(TOKENS)
    about = load_object(ABOUT)
    home = load_object(HOME)
    contact = load_object(CONTACT)
    not_found = load_object(NOT_FOUND)
    from build_styles import build_css
    from terminal_data import render_terminal_json

    return {
        OUTPUTS["core"]: render_core(details),
        OUTPUTS["philosophy"]: render_philosophy(details),
        OUTPUTS["tokens"]: render_tokens(tokens),
        OUTPUTS["about_intro"]: render_about_intro(about),
        OUTPUTS["about_sections"]: render_about_sections(about),
        OUTPUTS["home_hero"]: render_hero(home),
        OUTPUTS["home_sections"]: render_sections(home),
        OUTPUTS["contact"]: render_contact(contact),
        OUTPUTS["not_found"]: render_not_found(not_found),
        OUTPUTS["stylesheet"]: build_css(),
        OUTPUTS["terminal"]: render_terminal_json(),
    }


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true",
                        help="Fail if committed generated files are stale; do not write anything.")
    args = parser.parse_args(argv)
    stale = []
    for path, content in generated_files().items():
        previous = path.read_text(encoding="utf-8") if path.exists() else None
        if previous == content:
            print(f"OK: {path.relative_to(ROOT)}")
            continue
        if args.check:
            stale.append(str(path.relative_to(ROOT)))
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8")
            print(f"Generated: {path.relative_to(ROOT)}")
    if stale:
        print("Stale generated files: " + ", ".join(stale), file=sys.stderr)
        print("Run: python .github/scripts/generate_site_content.py", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
